<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Composition with Red, Blue and Yellow — Piet Mondrian, 1930</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Archivo:wght@400;500;700&family=Archivo+Black&display=swap" rel="stylesheet">
<style>
  :root{
    --red:#d93025;
    --blue:#2456b3;
    --yellow:#f2c230;
    --black:#111111;
    --white:#ffffff;
    --grey:#e8e8e8;
    --line:14px;
  }
  *{margin:0;padding:0;box-sizing:border-box}
  html{scroll-behavior:smooth}
  body{
    font-family:'Archivo',sans-serif;
    background:var(--white);
    color:var(--black);
    line-height:1.5;
  }
  .grid{
    display:grid;
    grid-template-columns:repeat(12,1fr);
    grid-auto-rows:minmax(60px,auto);
    gap:var(--line);
    background:var(--black);
    min-height:100vh;
    padding:var(--line);
  }
  .cell{background:var(--white);padding:28px;overflow:hidden}
  .span-3{grid-column:span 3}
  .span-4{grid-column:span 4}
  .span-5{grid-column:span 5}
  .span-6{grid-column:span 6}
  .span-7{grid-column:span 7}
  .span-8{grid-column:span 8}
  .span-12{grid-column:span 12}
  .row-2{grid-row:span 2}
  .row-3{grid-row:span 3}
  .row-4{grid-row:span 4}

  /* colour blocks — the painting itself, reduced to the page */
  .block-red{background:var(--red)}
  .block-blue{background:var(--blue)}
  .block-yellow{background:var(--yellow)}
  .block-grey{background:var(--grey)}
  .block-black{background:var(--black)}

  /* type */
  .kicker{
    font-size:12px;
    font-weight:700;
    letter-spacing:.18em;
    text-transform:uppercase;
    margin-bottom:14px;
  }
  h1{
    font-family:'Archivo Black',sans-serif;
    font-size:clamp(34px,4.6vw,64px);
    line-height:1.02;
    letter-spacing:-.01em;
    margin-bottom:16px;
  }
  h2{
    font-family:'Archivo Black',sans-serif;
    font-size:clamp(22px,2.4vw,32px);
    line-height:1.1;
    margin-bottom:14px;
  }
  p{font-size:17px;max-width:52ch}
  p + p{margin-top:12px}
  .on-dark{color:var(--white)}
  .on-dark .kicker{color:var(--yellow)}
  .on-dark a{color:var(--yellow)}
  .on-red .kicker{color:var(--white)}

  /* facts list */
  .facts{list-style:none}
  .facts li{
    display:flex;
    justify-content:space-between;
    gap:16px;
    padding:10px 0;
    border-bottom:2px solid var(--black);
    font-size:16px;
  }
  .facts li:last-child{border-bottom:none}
  .facts .k{font-weight:700;white-space:nowrap}
  .facts .v{text-align:right}

  /* principles: the neoplastic rules as the page's own rules */
  .principle{
    display:flex;
    align-items:center;
    gap:18px;
    padding:14px 0;
    border-bottom:2px solid var(--black);
  }
  .principle:last-child{border-bottom:none}
  .principle .swatch{
    flex:0 0 auto;
    width:44px;height:44px;
    border:3px solid var(--black);
  }
  .swatch-lines{
    background:
      linear-gradient(var(--black),var(--black)) 50% 0/3px 100% no-repeat,
      linear-gradient(var(--black),var(--black)) 0 50%/100% 3px no-repeat,
      var(--white);
  }
  .swatch-tri{
    background:
      linear-gradient(var(--red),var(--red)) 0 0/33.3% 100% no-repeat,
      linear-gradient(var(--blue),var(--blue)) 33.3% 0/33.3% 100% no-repeat,
      linear-gradient(var(--yellow),var(--yellow)) 66.6% 0/33.4% 100% no-repeat;
  }
  .swatch-non{
    background:
      linear-gradient(var(--white),var(--white)) 0 0/33.3% 100% no-repeat,
      linear-gradient(var(--grey),var(--grey)) 33.3% 0/33.3% 100% no-repeat,
      linear-gradient(var(--black),var(--black)) 66.6% 0/33.4% 100% no-repeat;
  }
  .principle p{font-size:15px}

  /* CTA */
  .cta{
    display:inline-block;
    margin-top:22px;
    padding:16px 30px;
    background:var(--black);
    color:var(--white);
    text-decoration:none;
    font-weight:700;
